class Solution {
public:
    int maxIncreasingCells(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        vector<array<int,3>> cells;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) cells.push_back({mat[i][j], i, j});
        sort(cells.begin(), cells.end());
        vector<int> row(m, 0), col(n, 0);
        int ans = 0;
        size_t i = 0;
        while (i < cells.size()) {
            int v = cells[i][0];
            vector<array<int,3>> upd;
            while (i < cells.size() && cells[i][0] == v) {
                int r = cells[i][1], c = cells[i][2];
                int d = max(row[r], col[c]) + 1;
                upd.push_back({r, c, d});
                ans = max(ans, d);
                i++;
            }
            for (auto& u : upd) {
                row[u[0]] = max(row[u[0]], u[2]);
                col[u[1]] = max(col[u[1]], u[2]);
            }
        }
        return ans;
    }
};

