class Solution {
    public int maxIncreasingCells(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        int[][] cells = new int[m * n][3];
        int idx = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) { cells[idx][0] = mat[i][j]; cells[idx][1] = i; cells[idx][2] = j; idx++; }
        Arrays.sort(cells, (a, b) -> Integer.compare(a[0], b[0]));
        int[] row = new int[m], col = new int[n];
        int ans = 0, i = 0;
        while (i < cells.length) {
            int v = cells[i][0];
            List<int[]> upd = new ArrayList<>();
            while (i < cells.length && cells[i][0] == v) {
                int r = cells[i][1], c = cells[i][2];
                int d = Math.max(row[r], col[c]) + 1;
                upd.add(new int[]{r, c, d});
                ans = Math.max(ans, d);
                i++;
            }
            for (int[] u : upd) {
                row[u[0]] = Math.max(row[u[0]], u[2]);
                col[u[1]] = Math.max(col[u[1]], u[2]);
            }
        }
        return ans;
    }
}

