var maxIncreasingCells = function(mat) {
    const m = mat.length, n = mat[0].length;
    const cells = [];
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++) cells.push([mat[i][j], i, j]);
    cells.sort((a, b) => a[0] - b[0]);
    const row = new Array(m).fill(0), col = new Array(n).fill(0);
    let ans = 0, i = 0;
    while (i < cells.length) {
        const v = cells[i][0], upd = [];
        while (i < cells.length && cells[i][0] === v) {
            const r = cells[i][1], c = cells[i][2];
            const d = Math.max(row[r], col[c]) + 1;
            upd.push([r, c, d]);
            ans = Math.max(ans, d);
            i++;
        }
        for (const [r, c, d] of upd) {
            row[r] = Math.max(row[r], d);
            col[c] = Math.max(col[c], d);
        }
    }
    return ans;
};
